# -*- coding: utf-8 -*-
"""R74 平台盲测 S6 席（B16/B17/B18，共 60 例）预测生成脚本。分段 append：每段写盘后断言例数与 id 集。"""
import json, os

OUT_DIR = "/home/hatch/workspace/divination/benchmark/phase3/runs/round74/predictions"
BATCHES_PATH = "/home/hatch/workspace/divination/benchmark/phase3/runs/round74/batches.json"

def trig(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def write_batch(key, preds):
    batches = json.load(open(BATCHES_PATH, encoding="utf-8"))
    ids = batches[key]
    assert set(preds.keys()) == set(ids), f"{key} id 集不合: {set(preds.keys()) ^ set(ids)}"
    assert len(preds) == len(ids) == 20, f"{key} 例数不合: {len(preds)}"
    os.makedirs(OUT_DIR, exist_ok=True)
    for cid in ids:
        p = preds[cid]
        if len(p) == 3:  # (text, basis, trigger)，confidence 由 CONF 映射补
            p = (p[0], p[1], CONF[cid], p[2])
        rec = {"case_id": cid, "prediction_text": p[0], "basis": p[1], "confidence": p[2], "trigger": p[3]}
        path = os.path.join(OUT_DIR, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # 逐件精确回读自验
    for cid in ids:
        path = os.path.join(OUT_DIR, cid + ".json")
        rec = json.load(open(path, encoding="utf-8"))
        assert rec["case_id"] == cid and rec["prediction_text"] and 0 <= rec["confidence"] <= 1
        assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    print(f"{key} 已写并自验 {len(ids)} 件")

